#!/usr/bin/env node
/**
 * tests/adversarial-ui-m4-challenger2.js
 * 
 * Milestone UI-M4 Empirical Adversarial Challenger 2 Test Suite
 * Archetype: EMPIRICAL CHALLENGER (Critic & Specialist)
 * 
 * Adversarial Testing Dimensions:
 * 1. Modal Focus Trapping: 100+ random directional keystroke hammering on:
 *    - Search virtual keyboard (.tv-keyboard-container)
 *    - Details modal overlay (#view-details)
 *    - Player subtitles modal (#player-subtitles-modal)
 *    - Player server modal (#player-server-modal)
 *    - Player error dialog (#player-error-dialog)
 *    Zero focus leakage to underlying inactive views or header.
 * 2. Trap Stack Switching & Nested Semantics:
 *    - Sequential trap switching (sibling panes, e.g. keyboard -> results grid) cleans up on single untrap.
 *    - Stacked/nested modal dialogs (parent -> child -> untrap -> parent restored -> untrap -> cleared).
 *    - Stack reset via untrap({ clearAll: true }).
 *    - Rapid 50-cycle trap/untrap churn.
 * 3. Focus Recovery & Self-Healing:
 *    - Removal / detachment of active focused element inside each trapped modal.
 *    - Immediate self-healing to a valid candidate inside the active trap without escaping.
 *    - Resilient handling of empty or disconnected candidate pools.
 * 4. Search Keyboard Re-entry Trap Hardening:
 *    - Navigation from virtual keyboard down to results grid releases trap.
 *    - Navigation back up into keyboard auto-re-engages trap.
 *    - 25x rapid ArrowUp hammering on Row 1 (zero leakage into header).
 *    - Left/Right boundary containment.
 * 5. Remote Back Key (461 / 27) 50x Rapid Bursts & Zero Circular Loops:
 *    - Deep hierarchy: Home -> Movies -> Details -> Player -> Subtitles Modal.
 *    - 50 consecutive Back key triggers in rapid succession.
 *    - Strict topological acyclicity: settles cleanly on Home view with zero circular bounce, zero crashes.
 *    - Chaotic interleaved Back + D-pad bursts.
 * 6. LG Magic Remote Keycode 10252 (VK_PLAY_PAUSE):
 *    - Verified in SpatialNav key resolution (MEDIA_PLAY_PAUSE).
 *    - Verified in Player OSD playback toggle.
 */

const fs = require('fs');
const path = require('path');
const assert = require('assert');

// 1. Resolve JSDOM
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      console.error('FATAL: JSDOM module could not be resolved.');
      process.exit(1);
    }
  }
}

// 2. Terminal Styling
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  yellow: '\x1b[33m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m',
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;
const failureList = [];

async function check(category, testName, fn) {
  totalChecks++;
  const idStr = totalChecks.toString().padStart(2, '0');
  const label = `[ADV-UI-M4-${idStr}] [${category}] ${testName}`;
  const start = Date.now();
  try {
    await fn();
    passedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.green}✓ PASS${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
  } catch (err) {
    failedChecks++;
    failureList.push({ label, error: err.message, stack: err.stack });
    console.log(`  ${C.red}✗ FAIL${C.reset} ${label}`);
    console.log(`    ${C.red}Error: ${err.message}${C.reset}`);
  }
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

// 3. Layout and Video Mocks
function installLayoutMock(window) {
  function makeRect(left, top, width, height) {
    return {
      left: left, top: top, width: width, height: height,
      right: left + width, bottom: top + height, x: left, y: top
    };
  }

  window.Element.prototype.getBoundingClientRect = function () {
    if (this.style && this.style.display === 'none') return makeRect(0, 0, 0, 0);

    const id = this.id;
    // Header
    if (this.classList && this.classList.contains('brand-container')) return makeRect(96, 24, 200, 48);
    if (this.classList && this.classList.contains('nav-pill-item')) {
      const route = this.getAttribute('data-route');
      if (route === 'home') return makeRect(790, 28, 75, 40);
      if (route === 'movies') return makeRect(875, 28, 85, 40);
      if (route === 'series') return makeRect(970, 28, 80, 40);
      if (route === 'search') return makeRect(1060, 28, 80, 40);
    }

    // Details actions & buttons
    if (id === 'details-play-btn') return makeRect(96, 450, 180, 56);
    if (this.classList && this.classList.contains('cast-item')) {
      const idx = Array.from(this.parentElement ? this.parentElement.children : []).indexOf(this);
      return makeRect(96 + idx * 130, 600, 120, 160);
    }

    // Player OSD Controls
    if (id === 'player-back-btn') return makeRect(96, 54, 54, 54);
    if (id === 'osd-scrubber') return makeRect(96, 920, 1728, 12);
    if (id === 'osd-rewind-btn') return makeRect(815, 960, 54, 54);
    if (id === 'osd-play-btn') return makeRect(893, 953, 68, 68);
    if (id === 'osd-forward-btn') return makeRect(985, 960, 54, 54);
    if (id === 'osd-subtitles-btn') return makeRect(1420, 960, 180, 52);
    if (id === 'osd-server-btn') return makeRect(1616, 960, 180, 52);

    // Player Modals & Close buttons
    if (id === 'player-subtitles-close-btn') return makeRect(1220, 260, 44, 44);
    if (id === 'player-server-close-btn') return makeRect(1220, 260, 44, 44);
    if (this.classList && this.classList.contains('modal-list-item')) {
      const p = this.parentElement;
      const idx = p ? Array.from(p.children).indexOf(this) : 0;
      return makeRect(660, 320 + idx * 64, 600, 56);
    }

    // Player Error Dialog Buttons
    if (id === 'player-error-retry-btn') return makeRect(740, 580, 180, 52);
    if (id === 'player-error-switch-btn') return makeRect(940, 580, 160, 52);
    if (id === 'player-error-exit-btn') return makeRect(1120, 580, 160, 52);

    // Keyboard buttons (Grid: rows 0..4, cols 0..9)
    if (this.classList && this.classList.contains('key-btn')) {
      const rowEl = this.closest('.keyboard-row');
      const rIdx = rowEl && rowEl.parentElement ? Array.from(rowEl.parentElement.children).indexOf(rowEl) : 0;
      const cIdx = rowEl ? Array.from(rowEl.children).indexOf(this) : 0;
      return makeRect(96 + cIdx * 64, 220 + rIdx * 64, 56, 56);
    }

    // Search Results Cards
    if (this.classList && this.classList.contains('card-poster')) {
      const p = this.parentElement;
      const idx = p ? Array.from(p.children).indexOf(this) : 0;
      const col = idx % 6;
      const row = Math.floor(idx / 6);
      return makeRect(96 + col * 288, 680 + row * 424, 264, 396);
    }

    return makeRect(96, 100, 100, 40);
  };

  window.Element.prototype.scrollIntoView = function () {};
  window.Element.prototype.scrollTo = function () {};
}

function installVideoMock(window) {
  const proto = window.HTMLMediaElement.prototype;
  function getState(el) {
    if (!el._mediaState) {
      el._mediaState = {
        currentTime: 0,
        duration: 7200,
        paused: true,
        ended: false,
        seeking: false,
        readyState: 4,
        bufferedRanges: [[0, 7200]],
        playbackRate: 1.0,
        volume: 1.0,
        muted: false,
        textTracks: [],
        error: null,
        src: ''
      };
    }
    return el._mediaState;
  }
  Object.defineProperty(proto, 'currentTime', {
    get: function () { return getState(this).currentTime; },
    set: function (val) {
      const s = getState(this);
      const num = Number(val);
      if (isNaN(num) || !isFinite(num)) throw new TypeError("Non-finite currentTime");
      s.currentTime = Math.max(0, Math.min(s.duration, num));
    },
    configurable: true
  });
  Object.defineProperty(proto, 'duration', {
    get: function () { return getState(this).duration; },
    set: function (val) { getState(this).duration = Number(val) || 0; },
    configurable: true
  });
  Object.defineProperty(proto, 'paused', {
    get: function () { return getState(this).paused; },
    configurable: true
  });
  Object.defineProperty(proto, 'buffered', {
    get: function () {
      const s = getState(this);
      return {
        length: s.bufferedRanges.length,
        start: function (idx) { return s.bufferedRanges[idx][0]; },
        end: function (idx) { return s.bufferedRanges[idx][1]; }
      };
    },
    configurable: true
  });
  proto.play = function () {
    const s = getState(this);
    s.paused = false;
    return Promise.resolve();
  };
  proto.pause = function () {
    const s = getState(this);
    s.paused = true;
  };
  proto.load = function () {};
}

function buildCleanEnv() {
  const projectRoot = path.resolve(__dirname, '..');
  const htmlPath = path.join(projectRoot, 'app', 'index.html');
  const html = fs.readFileSync(htmlPath, 'utf8');

  const dom = new JSDOM(html, {
    url: 'http://localhost:8088',
    pretendToBeVisual: true,
    runScripts: 'dangerously'
  });

  const { window } = dom;
  installLayoutMock(window);
  installVideoMock(window);

  // Storage Mock
  const storage = {};
  window.localStorage = {
    getItem: function (k) { return storage[k] || null; },
    setItem: function (k, v) { storage[k] = String(v); },
    removeItem: function (k) { delete storage[k]; },
    clear: function () { Object.keys(storage).forEach(k => delete storage[k]); }
  };

  // Mock Hls
  window.Hls = function () {
    this.attachMedia = function () {};
    this.loadSource = function () {};
    this.destroy = function () {};
    this.on = function () {};
    this.subtitleTracks = [
      { id: 0, lang: 'en', name: 'English' },
      { id: 1, lang: 'es', name: 'Spanish' }
    ];
    this.subtitleTrack = -1;
  };
  window.Hls.isSupported = function () { return true; };
  window.Hls.Events = {
    MANIFEST_PARSED: 'hlsManifestParsed',
    ERROR: 'hlsError',
    SUBTITLE_TRACKS_UPDATED: 'hlsSubtitleTracksUpdated',
    SUBTITLE_TRACK_SWITCH: 'hlsSubtitleTrackSwitch'
  };
  window.Hls.ErrorTypes = { NETWORK_ERROR: 'networkError', MEDIA_ERROR: 'mediaError', OTHER_ERROR: 'otherError' };

  // Load scripts into window in order
  const loadScript = function (relPath) {
    const full = path.join(projectRoot, relPath);
    const code = fs.readFileSync(full, 'utf8');
    window.eval(code);
  };

  loadScript('app/js/config.js');
  loadScript('app/js/navigation.js');
  loadScript('app/js/views/home.js');
  loadScript('app/js/views/catalog.js');
  loadScript('app/js/views/details.js');
  loadScript('app/js/views/search.js');
  loadScript('app/js/player.js');
  loadScript('app/js/app.js');

  return { dom, window, projectRoot };
}

// -----------------------------------------------------------------------------
// MAIN TEST HARNESS RUNNER
// -----------------------------------------------------------------------------
async function runAllChallengerTests() {
  console.log(`\n${C.bold}${C.magenta}========================================================================${C.reset}`);
  console.log(`${C.bold}${C.magenta}► CINEJOY webOS - EMPIRICAL ADVERSARIAL CHALLENGER 2 (MILESTONE UI-M4)${C.reset}`);
  console.log(`${C.bold}${C.magenta}========================================================================${C.reset}`);
  console.log(`  ${C.gray}Focus Trapping, Trap Stacking, Self-Healing & Rapid Back Key Bursts${C.reset}\n`);

  // ===========================================================================
  // SECTION 1: MODAL FOCUS TRAPPING (100+ KEYSTROKE HAMMERING PER MODAL)
  // ===========================================================================
  console.log(`${C.bold}${C.cyan}▶ SECTION 1: Modal Focus Trapping (100+ Keystroke Hammering)${C.reset}`);

  // Test 1: Virtual Keyboard Focus Trapping (120 Keystrokes)
  await check('TRAP_HAMMER', 'Search Virtual Keyboard (.tv-keyboard-container) 120-Keystroke Hammering', () => {
    const { window } = buildCleanEnv();
    const app = window.CinejoyApp;
    const nav = window.SpatialNav;
    app.init();
    app.switchView('search');

    const kbContainer = window.document.querySelector('.tv-keyboard-container');
    assert(kbContainer, 'Virtual keyboard container must exist');
    assert.strictEqual(nav.isTrapped(), true, 'Navigation must be trapped on search activation');
    assert.strictEqual(nav.activeTrap, kbContainer, 'Active trap must be keyboard container');

    const directions = ['up', 'down', 'left', 'right'];
    const keyCodes = { up: 38, down: 40, left: 37, right: 39 };

    for (let i = 0; i < 120; i++) {
      nav.resetThrottle();
      const dir = directions[i % 4];
      nav.handleKeyDown({ keyCode: keyCodes[dir], preventDefault: () => {} });

      const current = nav.getCurrentFocus();
      assert(current, `Focus must not be null at keystroke ${i}`);
      assert(kbContainer.contains(current), `Focus escaped keyboard at keystroke ${i} (focused: ${current.className})`);
      assert(!current.closest('.app-header'), `Focus leaked to header at keystroke ${i}`);
    }
  });

  // Test 2: Details Modal Overlay Focus Trapping (120 Keystrokes)
  await check('TRAP_HAMMER', 'Details Modal Overlay (#view-details) 120-Keystroke Hammering', () => {
    const { window } = buildCleanEnv();
    const app = window.CinejoyApp;
    const nav = window.SpatialNav;
    app.init();
    app.switchView('details');

    const detailsView = window.document.getElementById('view-details');
    assert(detailsView, 'Details view must exist');
    nav.trap(detailsView);

    const playBtn = window.document.getElementById('details-play-btn');
    if (playBtn) nav.setFocus(playBtn);

    const directions = ['right', 'down', 'left', 'up', 'down', 'down', 'up'];
    const keyCodes = { up: 38, down: 40, left: 37, right: 39 };

    for (let i = 0; i < 120; i++) {
      nav.resetThrottle();
      const dir = directions[i % directions.length];
      nav.handleKeyDown({ keyCode: keyCodes[dir], preventDefault: () => {} });

      const current = nav.getCurrentFocus();
      assert(current, `Focus must not be null at keystroke ${i}`);
      assert(detailsView.contains(current), `Focus escaped details view at keystroke ${i}`);
      assert(!current.closest('#view-home') && !current.closest('.app-header'),
        `Focus leaked outside details modal at keystroke ${i}`);
    }
    nav.untrap();
  });

  // Test 3: Player Subtitles Modal Focus Trapping (120 Keystrokes)
  await check('TRAP_HAMMER', 'Player Subtitles Modal (#player-subtitles-modal) 120-Keystroke Hammering', () => {
    const { window } = buildCleanEnv();
    const app = window.CinejoyApp;
    const nav = window.SpatialNav;
    app.init();
    app.switchView('player');

    const subsModal = window.document.getElementById('player-subtitles-modal');
    assert(subsModal, 'Subtitles modal must exist');
    subsModal.style.display = 'flex';
    nav.trap(subsModal);

    const firstItem = subsModal.querySelector('.modal-list-item[data-nav="true"]');
    assert(firstItem, 'Subtitles modal must have navigable item');
    nav.setFocus(firstItem);

    const directions = ['up', 'down', 'left', 'right'];
    const keyCodes = { up: 38, down: 40, left: 37, right: 39 };

    for (let i = 0; i < 120; i++) {
      nav.resetThrottle();
      const dir = directions[i % 4];
      nav.handleKeyDown({ keyCode: keyCodes[dir], preventDefault: () => {} });

      const current = nav.getCurrentFocus();
      assert(current, `Focus must not be null at keystroke ${i}`);
      assert(subsModal.contains(current), `Focus escaped subtitles modal at keystroke ${i}`);
      assert(!current.closest('#osd-hud-container'), `Focus leaked to player OSD controls at keystroke ${i}`);
    }
    nav.untrap();
  });

  // Test 4: Player Server Modal Focus Trapping (120 Keystrokes)
  await check('TRAP_HAMMER', 'Player Server Modal (#player-server-modal) 120-Keystroke Hammering', () => {
    const { window } = buildCleanEnv();
    const app = window.CinejoyApp;
    const nav = window.SpatialNav;
    app.init();
    app.switchView('player');

    const serverModal = window.document.getElementById('player-server-modal');
    assert(serverModal, 'Server modal must exist');
    serverModal.style.display = 'flex';
    nav.trap(serverModal);

    const firstServer = serverModal.querySelector('.modal-list-item[data-nav="true"]');
    assert(firstServer, 'Server modal must have navigable item');
    nav.setFocus(firstServer);

    const directions = ['up', 'down', 'left', 'right', 'down', 'up'];
    const keyCodes = { up: 38, down: 40, left: 37, right: 39 };

    for (let i = 0; i < 120; i++) {
      nav.resetThrottle();
      const dir = directions[i % directions.length];
      nav.handleKeyDown({ keyCode: keyCodes[dir], preventDefault: () => {} });

      const current = nav.getCurrentFocus();
      assert(current, `Focus must not be null at keystroke ${i}`);
      assert(serverModal.contains(current), `Focus escaped server modal at keystroke ${i}`);
      assert(!current.closest('#osd-hud-container'), `Focus leaked to player OSD at keystroke ${i}`);
    }
    nav.untrap();
  });

  // Test 5: Player Error Dialog Focus Trapping (120 Keystrokes)
  await check('TRAP_HAMMER', 'Player Error Dialog (#player-error-dialog) 120-Keystroke Hammering', () => {
    const { window } = buildCleanEnv();
    const app = window.CinejoyApp;
    const nav = window.SpatialNav;
    app.init();
    app.switchView('player');

    const errorDialog = window.document.getElementById('player-error-dialog');
    assert(errorDialog, 'Error dialog must exist');
    errorDialog.style.display = 'flex';
    nav.trap(errorDialog);

    const retryBtn = window.document.getElementById('player-error-retry-btn');
    assert(retryBtn, 'Retry button must exist');
    nav.setFocus(retryBtn);

    const directions = ['left', 'right', 'down', 'up', 'right', 'left'];
    const keyCodes = { up: 38, down: 40, left: 37, right: 39 };

    for (let i = 0; i < 120; i++) {
      nav.resetThrottle();
      const dir = directions[i % directions.length];
      nav.handleKeyDown({ keyCode: keyCodes[dir], preventDefault: () => {} });

      const current = nav.getCurrentFocus();
      assert(current, `Focus must not be null at keystroke ${i}`);
      assert(errorDialog.contains(current), `Focus escaped error dialog at keystroke ${i}`);
      assert(!current.closest('#osd-hud-container') && !current.closest('.app-header'),
        `Focus leaked outside error dialog at keystroke ${i}`);
    }
    nav.untrap();
  });

  // ===========================================================================
  // SECTION 2: TRAP STACK SWITCHING & NESTED MODAL SEMANTICS
  // ===========================================================================
  console.log(`\n${C.bold}${C.cyan}▶ SECTION 2: Trap Stack Switching & Nested Semantics${C.reset}`);

  // Test 6: Sequential Non-Modal Trap Switching (Sibling Panes)
  await check('STACK_SWITCH', 'Sequential Non-Modal Trap Switching (keyboard -> results) Clears Fully', () => {
    const { window } = buildCleanEnv();
    const nav = window.SpatialNav;
    nav.init();

    const kb = window.document.querySelector('.tv-keyboard-container');
    const results = window.document.querySelector('#search-results-grid');
    assert(kb && results, 'Keyboard and results grid must exist');

    nav.trap(kb);
    assert.strictEqual(nav.isTrapped(), true);
    assert.strictEqual(nav._trapStack.length, 1);

    // Sequentially switch to sibling results pane
    nav.trap(results);
    assert.strictEqual(nav.isTrapped(), true);
    assert.strictEqual(nav._trapStack.length, 1, 'Sibling switch must replace top trap instead of stacking');
    assert.strictEqual(nav.activeTrap, results);

    nav.untrap();
    assert.strictEqual(nav.isTrapped(), false, 'Single untrap must completely clear trapped state');
    assert.strictEqual(nav._trapStack.length, 0);
  });

  // Test 7: Nested Modal Trap Stacking & Unwinding
  await check('STACK_SWITCH', 'Nested Modal Dialog Trap Stack (Parent Modal -> Child Dialog -> Unwind)', () => {
    const { window } = buildCleanEnv();
    const nav = window.SpatialNav;
    nav.init();

    const detailsView = window.document.getElementById('view-details');
    const subsModal = window.document.getElementById('player-subtitles-modal');
    assert(detailsView && subsModal, 'Details and subs modal must exist');

    // 1. Trap parent modal
    nav.trap(detailsView);
    assert.strictEqual(nav.isTrapped(), true);
    assert.strictEqual(nav._trapStack.length, 1);
    assert.strictEqual(nav.activeTrap, detailsView);

    // 2. Open child modal on top
    subsModal.style.display = 'flex';
    nav.trap(subsModal);
    assert.strictEqual(nav.isTrapped(), true);
    assert.strictEqual(nav._trapStack.length, 2, 'Nested modal must push onto stack');
    assert.strictEqual(nav.activeTrap, subsModal);

    // 3. Close child modal
    nav.untrap();
    assert.strictEqual(nav.isTrapped(), true, 'Parent modal trap must remain active');
    assert.strictEqual(nav._trapStack.length, 1);
    assert.strictEqual(nav.activeTrap, detailsView);

    // 4. Close parent modal
    nav.untrap();
    assert.strictEqual(nav.isTrapped(), false, 'Untrapping parent modal must clear all traps');
    assert.strictEqual(nav._trapStack.length, 0);
    assert.strictEqual(nav.activeTrap, null);
  });

  // Test 8: untrap({ clearAll: true }) Stack Purge
  await check('STACK_SWITCH', 'Emergency Stack Reset via untrap({ clearAll: true })', () => {
    const { window } = buildCleanEnv();
    const nav = window.SpatialNav;
    nav.init();

    const d1 = window.document.getElementById('player-error-dialog');
    const d2 = window.document.getElementById('player-subtitles-modal');
    const d3 = window.document.getElementById('player-server-modal');

    nav.trap(d1);
    nav.trap(d2);
    nav.trap(d3);
    assert.strictEqual(nav._trapStack.length, 3);

    nav.untrap({ clearAll: true });
    assert.strictEqual(nav.isTrapped(), false);
    assert.strictEqual(nav._trapStack.length, 0);
    assert.strictEqual(nav.activeTrap, null);
  });

  // Test 9: Rapid 50-Cycle Trap/Untrap Alternation
  await check('STACK_SWITCH', 'Rapid 50-Cycle Trap/Untrap Churn Stress', () => {
    const { window } = buildCleanEnv();
    const nav = window.SpatialNav;
    nav.init();

    const modal = window.document.getElementById('player-server-modal');
    for (let c = 0; c < 50; c++) {
      nav.trap(modal);
      assert.strictEqual(nav.isTrapped(), true);
      nav.untrap();
      assert.strictEqual(nav.isTrapped(), false);
    }
    assert.strictEqual(nav._trapStack.length, 0);
  });

  // ===========================================================================
  // SECTION 3: FOCUS RECOVERY & TRAP-AWARE SELF-HEALING
  // ===========================================================================
  console.log(`\n${C.bold}${C.cyan}▶ SECTION 3: Focus Recovery & Trap-Aware Self-Healing${C.reset}`);

  // Test 10: Detached Focused Element Inside Subtitles Modal
  await check('SELF_HEALING', 'Detached Focused Item in Subtitles Modal Self-Heals Inside Trap', () => {
    const { window } = buildCleanEnv();
    const nav = window.SpatialNav;
    nav.init();

    const subsModal = window.document.getElementById('player-subtitles-modal');
    subsModal.style.display = 'flex';
    nav.trap(subsModal);

    const items = subsModal.querySelectorAll('.modal-list-item[data-nav="true"]');
    assert(items.length >= 2, 'Needs at least 2 items to test detachment');
    const targetItem = items[0];
    nav.setFocus(targetItem);
    assert.strictEqual(nav.getCurrentFocus(), targetItem);

    // Physically detach the focused element from DOM
    targetItem.remove();
    assert.strictEqual(window.document.body.contains(targetItem), false);

    // Trigger directional move
    nav.resetThrottle();
    const moved = nav.move('down');

    // Verify self-healing immediately recovered focus strictly within subsModal
    const current = nav.getCurrentFocus();
    assert(current, 'Self-healing must restore focus');
    assert(subsModal.contains(current), 'Self-healed focus must remain strictly inside the active trap');
    assert(current !== targetItem, 'Focus must have moved to a valid remaining candidate');
    nav.untrap();
  });

  // Test 11: Detached Focused Element Inside Server Modal
  await check('SELF_HEALING', 'Detached Focused Item in Server Modal Self-Heals Inside Trap', () => {
    const { window } = buildCleanEnv();
    const nav = window.SpatialNav;
    nav.init();

    const serverModal = window.document.getElementById('player-server-modal');
    serverModal.style.display = 'flex';
    nav.trap(serverModal);

    const items = serverModal.querySelectorAll('.modal-list-item[data-nav="true"]');
    assert(items.length >= 2, 'Needs at least 2 server items');
    const targetItem = items[1];
    nav.setFocus(targetItem);

    // Detach
    targetItem.remove();

    // Trigger move up
    nav.resetThrottle();
    nav.move('up');

    const current = nav.getCurrentFocus();
    assert(current, 'Self-healing must restore focus');
    assert(serverModal.contains(current), 'Focus must remain inside server modal');
    nav.untrap();
  });

  // Test 12: Detached Focused Element Inside Error Dialog
  await check('SELF_HEALING', 'Detached Retry Button in Error Dialog Self-Heals to Switch/Exit', () => {
    const { window } = buildCleanEnv();
    const nav = window.SpatialNav;
    nav.init();

    const errorDialog = window.document.getElementById('player-error-dialog');
    errorDialog.style.display = 'flex';
    nav.trap(errorDialog);

    const retryBtn = window.document.getElementById('player-error-retry-btn');
    assert(retryBtn, 'Retry button must exist');
    nav.setFocus(retryBtn);

    // Detach retry button
    retryBtn.remove();

    // Trigger move right
    nav.resetThrottle();
    nav.move('right');

    const current = nav.getCurrentFocus();
    assert(current, 'Self-healing must restore focus');
    assert(errorDialog.contains(current), 'Focus must remain inside error dialog');
    assert(current.id === 'player-error-switch-btn' || current.id === 'player-error-exit-btn',
      'Focus must fall back to remaining action buttons in error dialog');
    nav.untrap();
  });

  // Test 13: Detached Key in Virtual Keyboard Self-Heals
  await check('SELF_HEALING', 'Detached Key in Virtual Keyboard Recovers Focus to Sibling Key', () => {
    const { window } = buildCleanEnv();
    const app = window.CinejoyApp;
    const nav = window.SpatialNav;
    app.init();
    app.switchView('search');

    const keyQ = window.document.querySelector('.key-btn[data-key="Q"]');
    assert(keyQ, 'Key Q must exist');
    nav.setFocus(keyQ);

    // Detach Key Q
    keyQ.remove();

    nav.resetThrottle();
    nav.move('right');

    const current = nav.getCurrentFocus();
    assert(current, 'Focus must recover');
    const kbContainer = window.document.querySelector('.tv-keyboard-container');
    assert(kbContainer.contains(current), 'Recovered focus must be inside virtual keyboard');
  });

  // Test 14: Empty Trap Self-Healing Boundary Resilience
  await check('SELF_HEALING', 'Empty Trap Container Does Not Throw on Directional Move', () => {
    const { window } = buildCleanEnv();
    const nav = window.SpatialNav;
    nav.init();

    const emptyDiv = window.document.createElement('div');
    emptyDiv.id = 'empty-modal';
    emptyDiv.setAttribute('role', 'dialog');
    window.document.body.appendChild(emptyDiv);

    nav.trap(emptyDiv);
    nav.resetThrottle();

    // Directional move on empty trap should gracefully return null without throwing
    let threw = false;
    let res = null;
    try {
      res = nav.move('down');
    } catch (e) {
      threw = true;
    }
    assert.strictEqual(threw, false, 'Moving in empty trap must not throw');
    assert.strictEqual(res, null, 'Must return null when no candidates exist');

    nav.untrap();
    emptyDiv.remove();
  });

  // ===========================================================================
  // SECTION 4: SEARCH KEYBOARD RE-ENTRY TRAP HARDENING
  // ===========================================================================
  console.log(`\n${C.bold}${C.cyan}▶ SECTION 4: Search Keyboard Re-Entry Trap Hardening${C.reset}`);

  // Test 15: Keyboard Re-Entry from Results Grid Auto-Engages Trap
  await check('SEARCH_REENTRY', 'Keyboard Re-Entry from Results Grid Auto-Engages Focus Trap', () => {
    const { window } = buildCleanEnv();
    const app = window.CinejoyApp;
    const nav = window.SpatialNav;
    app.init();
    app.switchView('search');

    const searchView = app.views.search;
    assert(searchView, 'Search view controller must exist');

    // Populate mock results in grid
    const grid = window.document.getElementById('search-results-grid');
    grid.innerHTML = '';
    const mockCard = window.document.createElement('div');
    mockCard.className = 'card-poster';
    mockCard.setAttribute('data-nav', 'true');
    grid.appendChild(mockCard);

    // Jump to results
    searchView.jumpToResults();
    assert.strictEqual(nav.isTrapped(), false, 'Trap must be released when in results grid');
    assert.strictEqual(nav.getCurrentFocus(), mockCard);

    // Now navigate back up into the keyboard
    const firstKey = window.document.querySelector('.key-btn');
    assert(firstKey, 'Keyboard key must exist');
    nav.setFocus(firstKey);

    // Focus handler or focusin must auto-engage the trap
    assert.strictEqual(nav.isTrapped(), true, 'Focusing a keyboard key must re-engage SpatialNav trap');
    assert.strictEqual(nav.activeTrap, searchView.keyboard, 'Active trap must be keyboard element');
  });

  // Test 16: Row 1 ArrowUp 25x Hammering (Zero Upward Leakage into Header)
  await check('SEARCH_REENTRY', 'Row 1 (1..0) 25x ArrowUp Hammering Cannot Escape to Header', () => {
    const { window } = buildCleanEnv();
    const app = window.CinejoyApp;
    const nav = window.SpatialNav;
    app.init();
    app.switchView('search');

    const key1 = window.document.querySelector('.key-btn[data-key="1"]');
    assert(key1, 'Key 1 must exist on row 1');
    nav.setFocus(key1);

    // Hammer ArrowUp 25 times
    for (let h = 0; h < 25; h++) {
      nav.resetThrottle();
      nav.handleKeyDown({ keyCode: 38, key: 'ArrowUp', preventDefault: () => {} });

      const current = nav.getCurrentFocus();
      assert(current, `Focus must not be null on ArrowUp hammer ${h}`);
      assert(current.closest('.tv-keyboard-container'), `Focus escaped keyboard on ArrowUp hammer ${h}`);
      assert(!current.closest('.app-header'), `Focus leaked to header on ArrowUp hammer ${h}`);
      assert(!current.closest('.search-input-container'), `Focus leaked to input bar on ArrowUp hammer ${h}`);
    }
  });

  // Test 17: Left/Right Boundary Hammering on Keyboard Outer Columns
  await check('SEARCH_REENTRY', 'Left/Right Boundary Hammering Stays Strictly Inside Keyboard', () => {
    const { window } = buildCleanEnv();
    const app = window.CinejoyApp;
    const nav = window.SpatialNav;
    app.init();
    app.switchView('search');

    const keyQ = window.document.querySelector('.key-btn[data-key="Q"]');
    nav.setFocus(keyQ);

    // Hammer Left 20 times on leftmost column
    for (let l = 0; l < 20; l++) {
      nav.resetThrottle();
      nav.handleKeyDown({ keyCode: 37, key: 'ArrowLeft', preventDefault: () => {} });
      const cur = nav.getCurrentFocus();
      assert(cur && cur.closest('.tv-keyboard-container'), `Focus escaped on Left hammer ${l}`);
    }

    const keyP = window.document.querySelector('.key-btn[data-key="P"]') ||
                 window.document.querySelector('.key-btn[data-key="0"]');
    nav.setFocus(keyP);

    // Hammer Right 20 times on rightmost column
    for (let r = 0; r < 20; r++) {
      nav.resetThrottle();
      nav.handleKeyDown({ keyCode: 39, key: 'ArrowRight', preventDefault: () => {} });
      const cur = nav.getCurrentFocus();
      assert(cur && cur.closest('.tv-keyboard-container'), `Focus escaped on Right hammer ${r}`);
    }
  });

  // ===========================================================================
  // SECTION 5: REMOTE BACK KEY (461 / 27) 50X RAPID BURSTS & ZERO CIRCULAR LOOPS
  // ===========================================================================
  console.log(`\n${C.bold}${C.cyan}▶ SECTION 5: Remote Back Key (461 / 27) 50x Rapid Bursts${C.reset}`);

  // Test 18: 50x Rapid Back Key Bursts from Deepest View (Subtitles Modal)
  await check('BACK_HAMMER', '50x Rapid Back Key (461 / 27) Bursts Settle Cleanly on Home View', () => {
    const { window } = buildCleanEnv();
    const app = window.CinejoyApp;
    const nav = window.SpatialNav;
    app.init();

    // Deep navigation journey:
    // 1. Home -> Movies
    app.switchView('movies');
    assert.strictEqual(app.state.currentView, 'movies');

    // 2. Movies -> Details
    app.switchView('details');
    assert.strictEqual(app.state.currentView, 'details');

    // 3. Details -> Player
    app.switchView('player');
    assert.strictEqual(app.state.currentView, 'player');

    // 4. Open Subtitles Modal
    const subsModal = window.document.getElementById('player-subtitles-modal');
    subsModal.style.display = 'flex';
    app.playerOSD._activeModal = subsModal;
    nav.trap(subsModal);
    assert.strictEqual(nav.isTrapped(), true);

    const backKeyCodes = [461, 27];
    const viewSequence = [];

    // Rapid burst of 50 consecutive Back keys
    for (let b = 0; b < 50; b++) {
      const code = backKeyCodes[b % 2];
      nav.handleKeyDown({ keyCode: code, preventDefault: () => {} });
      viewSequence.push(app.state.currentView);
    }

    // Modal must be dismissed and untrapped
    assert.strictEqual(subsModal.style.display, 'none', 'Subtitles modal must be closed');
    assert.strictEqual(nav.isTrapped(), false, 'Traps must be cleared');

    // Final settled view must be Home
    assert.strictEqual(app.state.currentView, 'home', 'Must settle cleanly on Home view');

    // Verify topological acyclicity: once Home is reached, all subsequent Back keys remain on Home
    const firstHomeIndex = viewSequence.indexOf('home');
    assert(firstHomeIndex !== -1, 'Must reach home view');
    for (let k = firstHomeIndex; k < viewSequence.length; k++) {
      assert.strictEqual(viewSequence[k], 'home',
        `Circular loop detected! View at step ${k} jumped to ${viewSequence[k]} instead of staying on home`);
    }
  });

  // Test 19: Chaotic Interleaved Back + D-Pad Hammering
  await check('BACK_HAMMER', 'Chaotic Interleaved Back Key and D-Pad Hammering Settles Cleanly', () => {
    const { window } = buildCleanEnv();
    const app = window.CinejoyApp;
    const nav = window.SpatialNav;
    app.init();

    app.switchView('series');
    app.switchView('details');

    const randomKeys = [
      { keyCode: 38 }, // Up
      { keyCode: 461 }, // Back
      { keyCode: 40 }, // Down
      { keyCode: 27 },  // Back
      { keyCode: 37 }, // Left
      { keyCode: 39 }, // Right
      { keyCode: 461 }, // Back
      { keyCode: 13 }, // Enter
      { keyCode: 461 }  // Back
    ];

    for (let c = 0; c < 60; c++) {
      nav.resetThrottle();
      const k = randomKeys[c % randomKeys.length];
      nav.handleKeyDown({ keyCode: k.keyCode, preventDefault: () => {} });
    }

    // Must settle safely without crashing or leaving stray traps
    assert.strictEqual(app.state.currentView, 'home');
    assert.strictEqual(nav.isTrapped(), false);
  });

  // ===========================================================================
  // SECTION 6: LG MAGIC REMOTE KEYCODE 10252 (VK_PLAY_PAUSE)
  // ===========================================================================
  console.log(`\n${C.bold}${C.cyan}▶ SECTION 6: LG Magic Remote Keycode 10252 (VK_PLAY_PAUSE)${C.reset}`);

  // Test 20: Keycode 10252 in SpatialNav Engine
  await check('LG_REMOTE', 'SpatialNav Resolves Keycode 10252 as MEDIA_PLAY_PAUSE', () => {
    const { window } = buildCleanEnv();
    const nav = window.SpatialNav;
    nav.init();

    let emittedAction = null;
    let emittedCode = null;

    nav.on('mediakey', (data) => {
      emittedAction = data.action;
      emittedCode = data.keyCode;
    });

    nav.handleKeyDown({ keyCode: 10252, preventDefault: () => {} });

    assert.strictEqual(emittedAction, 'MEDIA_PLAY_PAUSE', 'Action must be MEDIA_PLAY_PAUSE');
    assert.strictEqual(emittedCode, 10252, 'Keycode must match 10252');
  });

  // Test 21: Keycode 10252 in Player OSD Controls
  await check('LG_REMOTE', 'Player OSD Toggles Play/Pause via LG Remote Keycode 10252', () => {
    const { window } = buildCleanEnv();
    const app = window.CinejoyApp;
    app.init();
    app.switchView('player');

    const playerOSD = app.playerOSD;
    assert(playerOSD, 'Player OSD controller must exist');

    const video = window.document.getElementById('main-video-player');
    assert(video, 'Video element must exist');

    // Simulate video playing
    video._mediaState.paused = false;

    // Send keycode 10252
    playerOSD.handleKeyDown({ keyCode: 10252, preventDefault: () => {} });
    assert.strictEqual(video.paused, true, 'Video must pause when keycode 10252 is received while playing');

    // Send keycode 10252 again
    playerOSD.handleKeyDown({ keyCode: 10252, preventDefault: () => {} });
    assert.strictEqual(video.paused, false, 'Video must resume when keycode 10252 is received while paused');
  });

  // ===========================================================================
  // SUMMARY AND VERDICT
  // ===========================================================================
  console.log(`\n${C.bold}${C.magenta}========================================================================${C.reset}`);
  console.log(`${C.bold}${C.magenta}► ADVERSARIAL CHALLENGER 2 EXECUTION SUMMARY${C.reset}`);
  console.log(`${C.bold}${C.magenta}========================================================================${C.reset}`);
  console.log(`  Total Checks:   ${totalChecks}`);
  console.log(`  Passed Checks:  ${C.green}${passedChecks}${C.reset}`);
  console.log(`  Failed Checks:  ${failedChecks > 0 ? C.red : C.green}${failedChecks}${C.reset}`);

  if (failureList.length > 0) {
    console.log(`\n${C.red}${C.bold}Failures Breakdown:${C.reset}`);
    failureList.forEach(f => {
      console.log(`  - ${f.label}`);
      console.log(`    ${f.error}`);
    });
  }

  const verdict = failedChecks === 0 ? 'APPROVE' : 'REJECT';
  console.log(`\nVERDICT: ${verdict === 'APPROVE' ? C.green : C.red}${C.bold}${verdict}${C.reset}\n`);

  if (failedChecks > 0) {
    process.exit(1);
  }
}

runAllChallengerTests().catch(err => {
  console.error('Fatal test error:', err);
  process.exit(1);
});

