#!/usr/bin/env node
/**
 * tests/adversarial-ui-m4-challenger2.js
 * 
 * Milestone UI-M4 Empirical Adversarial Challenger 2 Test Suite
 * Archetype: EMPIRICAL CHALLENGER (Critic & Specialist)
 * 
 * Adversarial Testing Dimensions:
 * 1. Modal Focus Trapping: 100+ random directional keystroke hammering on:
 *    - Search virtual keyboard (.tv-keyboard-container)
 *    - Details modal overlay (#view-details)
 *    - Player subtitles modal (#player-subtitles-modal)
 *    - Player server modal (#player-server-modal)
 *    - Player error dialog (#player-error-dialog)
 *    Zero focus leakage to underlying inactive views or header.
 * 2. Trap Stack Switching & Nested Semantics:
 *    - Sequential trap switching (sibling panes, e.g. keyboard -> results grid) cleans up on single untrap.
 *    - Stacked/nested modal dialogs (parent -> child -> untrap -> parent restored -> untrap -> cleared).
 *    - Stack reset via untrap({ clearAll: true }).
 *    - Rapid 50-cycle trap/untrap churn.
 * 3. Focus Recovery & Self-Healing:
 *    - Removal / detachment of active focused element inside each trapped modal.
 *    - Immediate self-healing to a valid candidate inside the active trap without escaping.
 *    - Resilient handling of empty or disconnected candidate pools.
 * 4. Search Keyboard Re-entry Trap Hardening:
 *    - Navigation from virtual keyboard down to results grid releases trap.
 *    - Navigation back up into keyboard auto-re-engages trap.
 *    - 25x rapid ArrowUp hammering on Row 1 (zero leakage into header).
 *    - Left/Right boundary containment.
 * 5. Remote Back Key (461 / 27) 50x Rapid Bursts & Zero Circular Loops:
 *    - Deep hierarchy: Home -> Movies -> Details -> Player -> Subtitles Modal.
 *    - 50 consecutive Back key triggers in rapid succession.
 *    - Strict topological acyclicity: settles cleanly on Home view with zero circular bounce, zero crashes.
 *    - Chaotic interleaved Back + D-pad bursts.
 * 6. LG Magic Remote Keycode 10252 (VK_PLAY_PAUSE):
 *    - Verified in SpatialNav key resolution (MEDIA_PLAY_PAUSE).
 *    - Verified in Player OSD playback toggle.
 */

const fs = require('fs');
const path = require('path');
const assert = require('assert');

// 1. Resolve JSDOM
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      console.error('FATAL: JSDOM module could not be resolved.');
      process.exit(1);
    }
  }
}

// 2. Terminal Styling
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  yellow: '\x1b[33m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m',
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;
const failureList = [];

async function check(category, testName, fn) {
  totalChecks++;
  const idStr = totalChecks.toString().padStart(2, '0');
  const label = `[ADV-UI-M4-${idStr}] [${category}] ${testName}`;
  const start = Date.now();
  try {
    await fn();
    passedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.green}✓ PASS${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
  } catch (err) {
    failedChecks++;
    failureList.push({ label, error: err.message, stack: err.stack });
    console.log(`  ${C.red}✗ FAIL${C.reset} ${label}`);
    console.log(`    ${C.red}Error: ${err.message}${C.reset}`);
  }
}

// 3. Layout and Video Mocks
function installLayoutMock(window) {
  function makeRect(left, top, width, height) {
    return {
      left: left, top: top, width: width, height: height,
      right: left + width, bottom: top + height, x: left, y: top
    };
  }

  window.Element.prototype.getBoundingClientRect = function () {
    if (this.style && this.style.display === 'none') return makeRect(0, 0, 0, 0);

    const id = this.id;
    // Header
    if (this.classList && this.classList.contains('brand-container')) return makeRect(96, 24, 200, 48);
    if (this.classList && this.classList.contains('nav-pill-item')) {
      const route = this.getAttribute('data-route');
      if (route === 'home') return makeRect(790, 28, 75, 40);
      if (route === 'movies') return makeRect(875, 28, 85, 40);
      if (route === 'series') return makeRect(970, 28, 80, 40);
      if (route === 'search') return makeRect(1060, 28, 80, 40);
    }

    // Details actions & buttons
    if (id === 'details-play-btn') return makeRect(96, 450, 180, 56);
    if (this.classList && this.classList.contains('cast-item')) {
      const idx = Array.from(this.parentElement ? this.parentElement.children : []).indexOf(this);
      return makeRect(96 + idx * 130, 600, 120, 160);
    }

    // Player OSD Controls
    if (id === 'player-back-btn') return makeRect(96, 54, 54, 54);
    if (id === 'osd-scrubber') return makeRect(96, 920, 1728, 12);
    if (id === 'osd-rewind-btn') return makeRect(815, 960, 54, 54);
    if (id === 'osd-play-btn') return makeRect(893, 953, 68, 68);
    if (id === 'osd-forward-btn') return makeRect(985, 960, 54, 54);
    if (id === 'osd-subtitles-btn') return makeRect(1420, 960, 180, 52);
    if (id === 'osd-server-btn') return makeRect(1616, 960, 180, 52);

    // Player Modals & Close buttons
    if (id === 'player-subtitles-close-btn') return makeRect(1220, 260, 44, 44);
    if (id === 'player-server-close-btn') return makeRect(1220, 260, 44, 44);
    if (this.classList && this.classList.contains('modal-list-item')) {
      const p = this.parentElement;
      const idx = p ? Array.from(p.children).indexOf(this) : 0;
      return makeRect(660, 320 + idx * 64, 600, 56);
    }

    // Player Error Dialog Buttons
    if (id === 'player-error-retry-btn') return makeRect(740, 580, 180, 52);
    if (id === 'player-error-switch-btn') return makeRect(940, 580, 160, 52);
    if (id === 'player-error-exit-btn') return makeRect(1120, 580, 160, 52);

    // Keyboard buttons (Grid: rows 0..4, cols 0..9)
    if (this.classList && this.classList.contains('key-btn')) {
      const rowEl = this.closest('.keyboard-row');
      const rIdx = rowEl && rowEl.parentElement ? Array.from(rowEl.parentElement.children).indexOf(rowEl) : 0;
      const cIdx = rowEl ? Array.from(rowEl.children).indexOf(this) : 0;
      return makeRect(96 + cIdx * 64, 220 + rIdx * 64, 56, 56);
    }

    // Search Results Cards
    if (this.classList && this.classList.contains('card-poster')) {
      const p = this.parentElement;
      const idx = p ? Array.from(p.children).indexOf(this) : 0;
      const col = idx % 6;
      const row = Math.floor(idx / 6);
      return makeRect(96 + col * 288, 680 + row * 424, 264, 396);
    }

    return makeRect(96, 100, 100, 40);
  };

  window.Element.prototype.scrollIntoView = function () {};
  window.Element.prototype.scrollTo = function () {};
}

function installVideoMock(window) {
  const proto = window.HTMLMediaElement.prototype;
  function getState(el) {
    if (!el._mediaState) {
      el._mediaState = {
        currentTime: 0,
        duration: 7200,
        paused: true,
        ended: false,
        seeking: false,
        readyState: 4,
        bufferedRanges: [[0, 7200]],
        playbackRate: 1.0,
        volume: 1.0,
        muted: false,
        textTracks: [],
        error: null,
        src: ''
      };
    }
    return el._mediaState;
  }
  Object.defineProperty(proto, 'currentTime', {
    get: function () { return getState(this).currentTime; },
    set: function (val) {
      const s = getState(this);
      const num = Number(val);
      if (isNaN(num) || !isFinite(num)) throw new TypeError("Non-finite currentTime");
      s.currentTime = Math.max(0, Math.min(s.duration, num));
    },
    configurable: true
  });
  Object.defineProperty(proto, 'duration', {
    get: function () { return getState(this).duration; },
    set: function (val) { getState(this).duration = Number(val) || 0; },
    configurable: true
  });
  Object.defineProperty(proto, 'paused', {
    get: function () { return getState(this).paused; },
    configurable: true
  });
  Object.defineProperty(proto, 'buffered', {
    get: function () {
      const s = getState(this);
      return {
        length: s.bufferedRanges.length,
        start: function (idx) { return s.bufferedRanges[idx][0]; },
        end: function (idx) { return s.bufferedRanges[idx][1]; }
      };
    },
    configurable: true
  });
  proto.play = function () {
    const s = getState(this);
    s.paused = false;
    return Promise.resolve();
  };
  proto.pause = function () {
    const s = getState(this);
    s.paused = true;
  };
  proto.load = function () {};
}

function buildCleanEnv() {
  const projectRoot = path.resolve(__dirname, '..');
  const htmlPath = path.join(projectRoot, 'app', 'index.html');
  const html = fs.readFileSync(htmlPath, 'utf8');

  const dom = new JSDOM(html, {
    url: 'http://localhost:8088',
    pretendToBeVisual: true,
    runScripts: 'dangerously'
  });

  const { window } = dom;
  installLayoutMock(window);
  installVideoMock(window);

  // Storage Mock
  const storage = {};
  window.localStorage = {
    getItem: function (k) { return storage[k] || null; },
    setItem: function (k, v) { storage[k] = String(v); },
    removeItem: function (k) { delete storage[k]; },
    clear: function () { Object.keys(storage).forEach(k => delete storage[k]); }
  };

  // Mock Hls
  window.Hls = function () {
    this.attachMedia = function () {};
    this.loadSource = function () {};
    this.destroy = function () {};
    this.on = function () {};
    this.subtitleTracks = [
      { id: 0, lang: 'en', name: 'English' },
      { id: 1, lang: 'es', name: 'Spanish' }
    ];
    this.subtitleTrack = -1;
  };
  window.Hls.isSupported = function () { return true; };
  window.Hls.Events = {
    MANIFEST_PARSED: 'hlsManifestParsed',
    ERROR: 'hlsError',
    SUBTITLE_TRACKS_UPDATED: 'hlsSubtitleTracksUpdated',
    SUBTITLE_TRACK_SWITCH: 'hlsSubtitleTrackSwitch'
  };
  window.Hls.ErrorTypes = { NETWORK_ERROR: 'networkError', MEDIA_ERROR: 'mediaError', OTHER_ERROR: 'otherError' };

  // Load scripts into window in order
  const loadScript = function (relPath) {
    const full = path.join(projectRoot, relPath);
    const code = fs.readFileSync(full, 'utf8');
    window.eval(code);
  };

  loadScript('app/js/config.js');
  loadScript('app/js/navigation.js');
  loadScript('app/js/views/home.js');
  loadScript('app/js/views/catalog.js');
  loadScript('app/js/views/details.js');
  loadScript('app/js/views/search.js');
  loadScript('app/js/player.js');
  loadScript('app/js/app.js');

  return { dom, window, projectRoot };
}

function getActiveTrapContainer(nav) {
  if (nav._trapStack && nav._trapStack.length > 0) {
    return nav._trapStack[nav._trapStack.length - 1].container;
  }
  return null;
}

// -----------------------------------------------------------------------------
// MAIN TEST HARNESS RUNNER
// -----------------------------------------------------------------------------
async function runAllChallengerTests() {
  console.log(`\n${C.bold}${C.magenta}========================================================================${C.reset}`);
  console.log(`${C.bold}${C.magenta}► CINEJOY webOS - EMPIRICAL ADVERSARIAL CHALLENGER 2 (MILESTONE UI-M4)${C.reset}`);
  console.log(`${C.bold}${C.magenta}========================================================================${C.reset}`);
  console.log(`  ${C.gray}Focus Trapping, Trap Stacking, Self-Healing & Rapid Back Key Bursts${C.reset}\n`);

  // ===========================================================================
  // SECTION 1: MODAL FOCUS TRAPPING (100+ KEYSTROKE HAMMERING PER MODAL)
  // ===========================================================================
  console.log(`${C.bold}${C.cyan}▶ SECTION 1: Modal Focus Trapping (100+ Keystroke Hammering)${C.reset}`);

  // Test 1: Virtual Keyboard Focus Trapping (120 Keystrokes)
  await check('TRAP_HAMMER', 'Search Virtual Keyboard (.tv-keyboard-container) 120-Keystroke Hammering', () => {
    const { window } = buildCleanEnv();
    const app = window.CinejoyApp;
    const nav = window.SpatialNav;
    app.init();
    app.switchView('search');

    const kbContainer = window.document.querySelector('.tv-keyboard-container');
    assert(kbContainer, 'Virtual keyboard container must exist');
    assert.strictEqual(nav.isTrapped(), true, 'Navigation must be trapped on search activation');
    assert.strictEqual(getActiveTrapContainer(nav), kbContainer, 'Active trap must be keyboard container');

    const directions = ['up', 'down', 'left', 'right'];
    const keyCodes = { up: 38, down: 40, left: 37, right: 39 };

    for (let i = 0; i < 120; i++) {
      nav.resetThrottle();
      const dir = directions[i % 4];
      nav.handleKeyDown({ keyCode: keyCodes[dir], preventDefault: () => {} });

      const current = nav.getCurrentFocus();
