// Test 21: Keycode 10252 in Player OSD Controls
await check('LG_REMOTE', 'Player OSD Toggles Play/Pause via LG Remote Keycode 10252', () => {
  const { window } = buildCleanEnv();
  const app = window.CinejoyApp;
  const playerCtrl = window.PlayerController;
  const osd = window.PlayerOSDController;
  assert(playerCtrl && osd, 'PlayerController and PlayerOSDController must exist');

  app.init();
  app.switchView('player');

  const video = window.document.getElementById('main-video-player');
  assert(video, 'Video element must exist');

  // Simulate video playing
  video._mediaState.paused = false;
  playerCtrl.state = 'PLAYING';

  // Dispatch keydown event with keyCode 10252 on window
  const evt1 = new window.KeyboardEvent('keydown', { keyCode: 10252, bubbles: true });
  Object.defineProperty(evt1, 'keyCode', { value: 10252 });
  window.dispatchEvent(evt1);

  assert.strictEqual(video.paused, true, 'Video must pause when keycode 10252 is received while playing');

  // Dispatch keydown event with keyCode 10252 again
  const evt2 = new window.KeyboardEvent('keydown', { keyCode: 10252, bubbles: true });
  Object.defineProperty(evt2, 'keyCode', { value: 10252 });
  window.dispatchEvent(evt2);

  assert.strictEqual(video.paused, false, 'Video must resume when keycode 10252 is received while paused');

  // Also test standalone _onKeyDown path when SpatialNav is disabled
  window.SpatialNav.disable();
  const evt3 = { keyCode: 10252, key: 'MediaPlayPause', preventDefault: () => {} };
  osd._onKeyDown(evt3);
  assert.strictEqual(video.paused, true, 'Fallback _onKeyDown must pause video');
  window.SpatialNav.enable();
});

